  9	import java.math.BigDecimal;
 10	import java.time.LocalDate;
 11	import java.time.YearMonth;
 12	import java.time.format.DateTimeFormatter;
 13	import java.util.*;
 14	import java.util.stream.Collectors;
 15	
 16	public class ReportService {
 17	    private static final String POUSADA_NAME = "Pousada Maré Alta";
 18	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 19	
 20	    private final ReservationRepository reservationRepository;
 21	    private final RoomRepository roomRepository;
 22	    private final PricingService pricingService;
 23	
 24	    public ReportService(ReservationRepository reservationRepository,
 25	                         RoomRepository roomRepository,
 26	                         PricingService pricingService) {
 27	        this.reservationRepository = reservationRepository;
 28	        this.roomRepository = roomRepository;
 29	        this.pricingService = pricingService;
 30	    }
 31	
 32	    public String generateOccupancyReport(LocalDate date) {
 33	        List<Reservation> occupiedReservations = reservationRepository.findPaidReservationsForNight(date)
 34	                .stream()
 35	                .sorted(Comparator.comparing(Reservation::getRoomNumber))
 36	                .toList();
 37	
 38	        int totalRooms = roomRepository.findAll().size();
 39	        int occupiedRooms = occupiedReservations.size();
 40	
 41	        ReportBuilder builder = new ReportBuilder();
 42	        builder.addTitleLine(POUSADA_NAME, "occupancy", date.format(DATE_FORMATTER));
 43	        builder.addHeaderLine("room", "type", "reservation", "check_in", "check_out");
 44	
 45	        for (Reservation reservation : occupiedReservations) {
 46	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
 47	            builder.addLine(
 48	                    reservation.getRoomNumber(),
 49	                    room.getType().toString(),
 50	                    String.valueOf(reservation.getId()),
 51	                    reservation.getCheckIn().format(DATE_FORMATTER),
 52	                    reservation.getCheckOut().format(DATE_FORMATTER)
 53	            );
 54	        }
 55	
 56	        builder.addTotalLine("total", occupiedRooms + "/" + totalRooms);
 57	
 58	        return builder.build();
 59	    }
 60	
 61	    public String generateRevenueReport(YearMonth month) {
 62	        List<Reservation> reservations = reservationRepository.findReservationsStartingInMonth(month)
 63	                .stream()
 64	                .filter(r -> r.getNetAmount().compareTo(BigDecimal.ZERO) > 0)
 65	                .sorted(Comparator.comparing(Reservation::getCheckIn)
 66	                        .thenComparing(Reservation::getId))
 67	                .toList();
 68	
 69	        BigDecimal totalRevenue = reservations.stream()
 70	                .map(Reservation::getNetAmount)
 71	                .reduce(BigDecimal.ZERO, BigDecimal::add);
 72	
 73	        ReportBuilder builder = new ReportBuilder();
 74	        builder.addTitleLine(POUSADA_NAME, "revenue", month.toString());
 75	        builder.addHeaderLine("reservation", "room", "check_in", "check_out", "status", "amount");
 76	
 77	        for (Reservation reservation : reservations) {
 78	            builder.addLine(
 79	                    String.valueOf(reservation.getId()),
 80	                    reservation.getRoomNumber(),
 81	                    reservation.getCheckIn().format(DATE_FORMATTER),
 82	                    reservation.getCheckOut().format(DATE_FORMATTER),
 83	                    reservation.getStatus().toString(),
 84	                    formatDecimal(reservation.getNetAmount())
 85	            );
 86	        }
 87	
 88	        builder.addTotalLine("total", formatDecimal(totalRevenue));
 89	
 90	        return builder.build();
 91	    }
 92	
 93	    public String generateTourismTaxReport(YearMonth month) {
 94	        List<Reservation> reservations = reservationRepository.findReservationsStartingInMonth(month)
 95	                .stream()
 96	                .filter(Reservation::isPaid)
 97	                .sorted(Comparator.comparing(Reservation::getCheckIn)
 98	                        .thenComparing(Reservation::getId))
 99	                .toList();
100	
101	        BigDecimal totalTax = BigDecimal.ZERO;
102	
103	        ReportBuilder builder = new ReportBuilder();
104	        builder.addTitleLine(POUSADA_NAME, "tourism-tax", month.toString());
105	        builder.addHeaderLine("reservation", "room", "check_in", "check_out", "guests", "nights", "tax");
106	
107	        for (Reservation reservation : reservations) {
108	            BigDecimal tax = pricingService.calculateTourismTax(reservation.getGuests(), reservation.getNights());
109	            totalTax = totalTax.add(tax);
110	
111	            builder.addLine(
112	                    String.valueOf(reservation.getId()),
113	                    reservation.getRoomNumber(),
114	                    reservation.getCheckIn().format(DATE_FORMATTER),
115	                    reservation.getCheckOut().format(DATE_FORMATTER),
116	                    String.valueOf(reservation.getGuests()),
117	                    String.valueOf(reservation.getNights()),
118	                    formatDecimal(tax)
119	            );
120	        }
121	
122	        builder.addTotalLine("total", formatDecimal(totalTax));
123	
124	        return builder.build();
125	    }
126	
127	    public String generateRatePlansReport(YearMonth month) {
128	        List<Reservation> reservations = reservationRepository.findReservationsStartingInMonth(month)
129	                .stream()
130	                .filter(r -> r.getNetAmount().compareTo(BigDecimal.ZERO) > 0)
131	                .toList();
132	
133	        Map<RatePlan, List<Reservation>> byPlan = reservations.stream()
134	                .collect(Collectors.groupingBy(Reservation::getRatePlan));
135	
136	        ReportBuilder builder = new ReportBuilder();
137	        builder.addTitleLine(POUSADA_NAME, "rate-plans", month.toString());
138	        builder.addHeaderLine("rate_plan", "reservations", "amount");
139	
140	        int totalCount = 0;
141	        BigDecimal totalAmount = BigDecimal.ZERO;
142	
143	        for (RatePlan plan : RatePlan.values()) {
144	            List<Reservation> planReservations = byPlan.getOrDefault(plan, Collections.emptyList());
145	            int count = planReservations.size();
146	            BigDecimal amount = planReservations.stream()
147	                    .map(Reservation::getNetAmount)
148	                    .reduce(BigDecimal.ZERO, BigDecimal::add);
149	
150	            builder.addLine(
151	                    plan.toString(),
152	                    String.valueOf(count),
153	                    formatDecimal(amount)
154	            );
155	
156	            totalCount += count;
157	            totalAmount = totalAmount.add(amount);
158	        }
159	
160	        builder.addTotalLine("total", String.valueOf(totalCount), formatDecimal(totalAmount));
161	
162	        return builder.build();
163	    }
164	
165	    private String formatDecimal(BigDecimal value) {
166	        return value.setScale(2).toPlainString();
167	    }
168	
169	    private static class ReportBuilder {
170	        private final StringBuilder sb = new StringBuilder();
171	
172	        public void addTitleLine(String... parts) {
173	            sb.append(String.join(",", parts)).append("\n");
174	        }
175	
176	        public void addHeaderLine(String... headers) {
177	            sb.append(String.join(",", headers)).append("\n");
178	        }
179	
180	        public void addLine(String... values) {
181	            sb.append(String.join(",", values)).append("\n");
182	        }
183	
184	        public void addTotalLine(String... values) {
185	            sb.append(String.join(",", values));
186	        }
187	
188	        public String build() {
189	            return sb.toString();
190	        }
191	    }
192	}

