  1	package com.pousadamarealta.repository;
  2	
  3	import com.pousadamarealta.domain.Reservation;
  4	import com.pousadamarealta.domain.ReservationStatus;
  5	
  6	import java.time.LocalDate;
  7	import java.time.YearMonth;
  8	import java.util.ArrayList;
  9	import java.util.List;
 10	import java.util.Optional;
 11	import java.util.concurrent.atomic.AtomicLong;
 12	
 13	public class ReservationRepository {
 14	    private final List<Reservation> reservations = new ArrayList<>();
 15	    private final AtomicLong idGenerator = new AtomicLong(0);
 16	
 17	    public Reservation save(Reservation reservation) {
 18	        reservations.add(reservation);
 19	        return reservation;
 20	    }
 21	
 22	    public Optional<Reservation> findById(long id) {
 23	        return reservations.stream()
 24	                .filter(r -> r.getId() == id)
 25	                .findFirst();
 26	    }
 27	
 28	    public List<Reservation> findAll() {
 29	        return new ArrayList<>(reservations);
 30	    }
 31	
 32	    public List<Reservation> findByRoomAndDateRange(String roomNumber, LocalDate checkIn, LocalDate checkOut) {
 33	        return reservations.stream()
 34	                .filter(r -> r.getRoomNumber().equals(roomNumber))
 35	                .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
 36	                .filter(r -> datesOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut))
 37	                .toList();
 38	    }
 39	
 40	    public List<Reservation> findPaidReservationsForNight(LocalDate date) {
 41	        return reservations.stream()
 42	                .filter(Reservation::isPaid)
 43	                .filter(r -> !r.getCheckIn().isAfter(date) && r.getCheckOut().isAfter(date))
 44	                .toList();
 45	    }
 46	
 47	    public List<Reservation> findReservationsStartingInMonth(YearMonth month) {
 48	        LocalDate start = month.atDay(1);
 49	        LocalDate end = month.atEndOfMonth();
 50	
 51	        return reservations.stream()
 52	                .filter(r -> !r.getCheckIn().isBefore(start) && !r.getCheckIn().isAfter(end))
 53	                .toList();
 54	    }
 55	
 56	    public long nextId() {
 57	        return idGenerator.incrementAndGet();
 58	    }
 59	
 60	    private boolean datesOverlap(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
 61	        return start1.isBefore(end2) && start2.isBefore(end1);
 62	    }
 63	}
