115	    private BigDecimal refund;
116	
117	    public Reservation(long id, String roomNumber, String guestName, String guestEmail, String guestCpf,
118	                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
119	                       int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
120	        this.id = id;
121	        this.roomNumber = roomNumber;
122	        this.guestName = guestName;
123	        this.guestEmail = guestEmail;
124	        this.guestCpf = guestCpf;
125	        this.checkIn = checkIn;
126	        this.checkOut = checkOut;
127	        this.guests = guests;
128	        this.ratePlan = ratePlan;
129	        this.nights = nights;
130	        this.subtotal = subtotal;
131	        this.discount = discount;
132	        this.total = total;
133	        this.status = ReservationStatus.PENDING;
134	        this.amountPaid = BigDecimal.ZERO;
135	        this.refund = null;
136	    }
137	
138	    public long getId() {
139	        return id;
140	    }
141	
142	    public String getRoomNumber() {
143	        return roomNumber;
144	    }
145	
146	    public String getGuestName() {
147	        return guestName;
148	    }
149	
150	    public String getGuestEmail() {
151	        return guestEmail;
152	    }
153	
154	    public String getGuestCpf() {
155	        return guestCpf;
156	    }
157	
158	    public LocalDate getCheckIn() {
159	        return checkIn;
160	    }
161	
162	    public LocalDate getCheckOut() {
163	        return checkOut;
164	    }
165	
166	    public int getGuests() {
167	        return guests;
168	    }
169	
170	    public RatePlan getRatePlan() {
171	        return ratePlan;
172	    }
173	
174	    public int getNights() {
175	        return nights;
176	    }
177	
178	    public BigDecimal getSubtotal() {
179	        return subtotal;
180	    }
181	
182	    public BigDecimal getDiscount() {
183	        return discount;
184	    }
185	
186	    public BigDecimal getTotal() {
187	        return total;
188	    }
189	
190	    public ReservationStatus getStatus() {
191	        return status;
192	    }
193	
194	    public void setStatus(ReservationStatus status) {
195	        this.status = status;
196	    }
197	
198	    public BigDecimal getAmountPaid() {
199	        return amountPaid;
200	    }
201	
202	    public void setAmountPaid(BigDecimal amountPaid) {
203	        this.amountPaid = amountPaid;
204	    }
205	
206	    public BigDecimal getRefund() {
207	        return refund;
208	    }
209	
210	    public void setRefund(BigDecimal refund) {
211	        this.refund = refund;
212	    }
213	
214	    public boolean isPaid() {
215	        return status == ReservationStatus.CONFIRMED ||
216	               status == ReservationStatus.CHECKED_IN ||
217	               status == ReservationStatus.CHECKED_OUT;
218	    }
219	
220	    public BigDecimal getNetAmount() {
221	        BigDecimal net = amountPaid;
222	        if (refund != null) {
223	            net = net.subtract(refund);
224	        }
225	        return net;
226	    }
227	}
