246	package com.pousadamarealta.service;
247	
248	import java.math.BigDecimal;
249	import java.math.RoundingMode;
250	import java.time.LocalDate;
251	import java.time.Month;
252	
253	public class PricingService {
254	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
255	    private static final BigDecimal TOURISM_TAX_PER_GUEST_PER_NIGHT = new BigDecimal("4.50");
256	
257	    public boolean isHighSeason(LocalDate date) {
258	        Month month = date.getMonth();
259	        int day = date.getDayOfMonth();
260	
261	        if (month == Month.DECEMBER && day >= 15) {
262	            return true;
263	        }
264	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
265	            return true;
266	        }
267	        if (month == Month.JULY) {
268	            return true;
269	        }
270	        return false;
271	    }
272	
273	    public BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate date) {
274	        BigDecimal price = baseRate;
275	        if (isHighSeason(date)) {
276	            price = price.multiply(HIGH_SEASON_MULTIPLIER);
277	        }
278	        return round(price);
279	    }
280	
281	    public BigDecimal round(BigDecimal value) {
282	        return value.setScale(2, RoundingMode.HALF_EVEN);
283	    }
284	
285	    public BigDecimal calculateTourismTax(int guests, int nights) {
286	        BigDecimal tax = TOURISM_TAX_PER_GUEST_PER_NIGHT
287	                .multiply(BigDecimal.valueOf(guests))
288	                .multiply(BigDecimal.valueOf(nights));
289	        return round(tax);
290	    }
291	}
