 10	import com.pousadamarealta.service.ReportService;
 11	import com.pousadamarealta.service.ReservationService;
 12	import io.javalin.http.Context;
 13	import io.javalin.http.HttpStatus;
 14	
 15	import java.time.LocalDate;
 16	import java.time.YearMonth;
 17	import java.time.format.DateTimeParseException;
 18	import java.util.HashMap;
 19	import java.util.List;
 20	import java.util.Map;
 21	import java.util.stream.Collectors;
 22	
 23	public class ApiHandler {
 24	    private final RoomRepository roomRepository;
 25	    private final ReservationService reservationService;
 26	    private final ReservationRepository reservationRepository;
 27	    private final MessageRepository messageRepository;
 28	    private final ReportService reportService;
 29	
 30	    public ApiHandler(RoomRepository roomRepository,
 31	                      ReservationService reservationService,
 32	                      ReservationRepository reservationRepository,
 33	                      MessageRepository messageRepository,
 34	                      ReportService reportService) {
 35	        this.roomRepository = roomRepository;
 36	        this.reservationService = reservationService;
 37	        this.reservationRepository = reservationRepository;
 38	        this.messageRepository = messageRepository;
 39	        this.reportService = reportService;
 40	    }
 41	
 42	    public void getRooms(Context ctx) {
 43	        List<Map<String, Object>> rooms = roomRepository.findAll().stream()
 44	                .map(room -> {
 45	                    Map<String, Object> map = new HashMap<>();
 46	                    map.put("number", room.getNumber());
 47	                    map.put("type", room.getType().toString());
 48	                    map.put("capacity", room.getCapacity());
 49	                    map.put("nightlyRate", room.getNightlyRate());
 50	                    return map;
 51	                })
 52	                .collect(Collectors.toList());
 53	
 54	        ctx.json(rooms);
 55	    }
 56	
 57	    public void createReservation(Context ctx) {
 58	        try {
 59	            JsonNode json = ctx.bodyAsClass(JsonNode.class);
 60	
 61	            String roomNumber = getRequiredString(json, "roomNumber");
 62	            String guestName = getRequiredString(json, "guestName");
 63	            String guestEmail = getRequiredString(json, "guestEmail");
 64	            String guestCpf = getRequiredString(json, "guestCpf");
 65	            LocalDate checkIn = getRequiredDate(json, "checkIn");
 66	            LocalDate checkOut = getRequiredDate(json, "checkOut");
 67	            int guests = getRequiredInt(json, "guests");
 68	            RatePlan ratePlan = getRequiredEnum(json, "ratePlan", RatePlan.class);
 69	
 70	            Reservation reservation = reservationService.createReservation(
 71	                    roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan);
 72	
 73	            ctx.status(HttpStatus.CREATED);
 74	            ctx.json(toReservationMap(reservation));
 75	        } catch (IllegalArgumentException e) {
 76	            ctx.status(HttpStatus.BAD_REQUEST);
 77	            ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
 78	        }
 79	    }
 80	
 81	    public void getReservation(Context ctx) {
 82	        long id = Long.parseLong(ctx.pathParam("id"));
 83	        Reservation reservation = reservationService.getReservation(id);
 84	        ctx.json(toReservationMap(reservation));
 85	    }
 86	
 87	    public void confirmReservation(Context ctx) {
 88	        long id = Long.parseLong(ctx.pathParam("id"));
 89	        Reservation reservation = reservationService.confirmReservation(id);
 90	        ctx.json(toReservationMap(reservation));
 91	    }
 92	
 93	    public void cancelReservation(Context ctx) {
 94	        long id = Long.parseLong(ctx.pathParam("id"));
 95	        Reservation reservation = reservationService.cancelReservation(id);
 96	        ctx.json(toReservationMap(reservation));
 97	    }
 98	
 99	    public void checkIn(Context ctx) {
100	        long id = Long.parseLong(ctx.pathParam("id"));
101	        Reservation reservation = reservationService.checkIn(id);
102	        ctx.json(toReservationMap(reservation));
103	    }
104	
105	    public void checkOut(Context ctx) {
106	        long id = Long.parseLong(ctx.pathParam("id"));
107	        ReceiptDocument receipt = reservationService.checkOut(id);
108	        ctx.json(toReceiptMap(receipt));
109	    }
110	
111	    public void getDocument(Context ctx) {
112	        long id = Long.parseLong(ctx.pathParam("id"));
113	        ReceiptDocument receipt = reservationService.getDocument(id);
114	        ctx.json(toReceiptMap(receipt));
115	    }
116	
117	    public void getMessages(Context ctx) {
118	        List<Map<String, Object>> messages = messageRepository.findAll().stream()
119	                .map(message -> {
120	                    Map<String, Object> map = new HashMap<>();
121	                    map.put("id", message.getId());
122	                    map.put("channel", message.getChannel());
123	                    map.put("to", message.getTo());
124	                    map.put("subject", message.getSubject());
125	                    map.put("body", message.getBody());
126	                    return map;
127	                })
128	                .collect(Collectors.toList());
129	
130	        ctx.json(messages);
131	    }
132	
133	    public void getOccupancyReport(Context ctx) {
134	        String dateParam = ctx.queryParam("date");
135	        if (dateParam == null) {
136	            ctx.status(HttpStatus.BAD_REQUEST);
137	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Date parameter is required"));
138	            return;
139	        }
140	
141	        try {
142	            LocalDate date = LocalDate.parse(dateParam);
143	            String csv = reportService.generateOccupancyReport(date);
144	            ctx.contentType("text/csv; charset=utf-8");
145	            ctx.result(csv);
146	        } catch (DateTimeParseException e) {
147	            ctx.status(HttpStatus.BAD_REQUEST);
148	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
149	        }
150	    }
151	
152	    public void getRevenueReport(Context ctx) {
153	        String monthParam = ctx.queryParam("month");
154	        if (monthParam == null) {
155	            ctx.status(HttpStatus.BAD_REQUEST);
156	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Month parameter is required"));
157	            return;
158	        }
159	
160	        try {
161	            YearMonth month = YearMonth.parse(monthParam);
162	            String csv = reportService.generateRevenueReport(month);
163	            ctx.contentType("text/csv; charset=utf-8");
164	            ctx.result(csv);
165	        } catch (DateTimeParseException e) {
166	            ctx.status(HttpStatus.BAD_REQUEST);
167	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
168	        }
169	    }
170	
171	    public void getTourismTaxReport(Context ctx) {
172	        String monthParam = ctx.queryParam("month");
173	        if (monthParam == null) {
174	            ctx.status(HttpStatus.BAD_REQUEST);
175	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Month parameter is required"));
176	            return;
177	        }
178	
179	        try {
180	            YearMonth month = YearMonth.parse(monthParam);
181	            String csv = reportService.generateTourismTaxReport(month);
182	            ctx.contentType("text/csv; charset=utf-8");
183	            ctx.result(csv);
184	        } catch (DateTimeParseException e) {
185	            ctx.status(HttpStatus.BAD_REQUEST);
186	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
187	        }
188	    }
189	
190	    public void getRatePlansReport(Context ctx) {
191	        String monthParam = ctx.queryParam("month");
192	        if (monthParam == null) {
193	            ctx.status(HttpStatus.BAD_REQUEST);
194	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Month parameter is required"));
195	            return;
196	        }
197	
198	        try {
199	            YearMonth month = YearMonth.parse(monthParam);
200	            String csv = reportService.generateRatePlansReport(month);
201	            ctx.contentType("text/csv; charset=utf-8");
202	            ctx.result(csv);
203	        } catch (DateTimeParseException e) {
204	            ctx.status(HttpStatus.BAD_REQUEST);
205	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
206	        }
207	    }
208	
