  9	import java.math.BigDecimal;
 10	import java.time.LocalDate;
 11	import java.time.temporal.ChronoUnit;
 12	
 13	public class ReservationService {
 14	    private final ReservationRepository reservationRepository;
 15	    private final RoomRepository roomRepository;
 16	    private final MessageRepository messageRepository;
 17	    private final PricingService pricingService;
 18	
 19	    public ReservationService(ReservationRepository reservationRepository,
 20	                              RoomRepository roomRepository,
 21	                              MessageRepository messageRepository,
 22	                              PricingService pricingService) {
 23	        this.reservationRepository = reservationRepository;
 24	        this.roomRepository = roomRepository;
 25	        this.messageRepository = messageRepository;
 26	        this.pricingService = pricingService;
 27	    }
 28	
 29	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail, String guestCpf,
 30	                                         LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
 31	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
 32	            throw new InvalidRequestException("Check-out date must be after check-in date");
 33	        }
 34	
 35	        if (guests < 1) {
 36	            throw new InvalidRequestException("Number of guests must be at least 1");
 37	        }
 38	
 39	        Room room = roomRepository.findByNumber(roomNumber)
 40	                .orElseThrow(() -> new RoomNotFoundException("Room " + roomNumber + " not found"));
 41	
 42	        if (guests > room.getCapacity()) {
 43	            throw new CapacityExceededException("Room " + roomNumber + " has capacity for " + room.getCapacity() + " guests");
 44	        }
 45	
 46	        if (!reservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut).isEmpty()) {
 47	            throw new RoomUnavailableException("Room " + roomNumber + " is not available for the selected dates");
 48	        }
 49	
 50	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
 51	        BigDecimal subtotal = calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
 52	        BigDecimal discount = calculateDiscount(subtotal, ratePlan);
 53	        BigDecimal total = pricingService.round(subtotal.subtract(discount));
 54	
 55	        long id = reservationRepository.nextId();
 56	        Reservation reservation = new Reservation(id, roomNumber, guestName, guestEmail, guestCpf,
 57	                checkIn, checkOut, guests, ratePlan, nights, subtotal, discount, total);
 58	
 59	        return reservationRepository.save(reservation);
 60	    }
 61	
 62	    public Reservation confirmReservation(long id) {
 63	        Reservation reservation = getReservation(id);
 64	
 65	        if (reservation.getStatus() != ReservationStatus.PENDING) {
 66	            throw new OperationNotAllowedException("Only pending reservations can be confirmed");
 67	        }
 68	
 69	        reservation.setStatus(ReservationStatus.CONFIRMED);
 70	        reservation.setAmountPaid(reservation.getTotal());
 71	
 72	        sendConfirmationEmail(reservation);
 73	
 74	        return reservation;
 75	    }
 76	
 77	    public Reservation cancelReservation(long id) {
 78	        Reservation reservation = getReservation(id);
 79	
 80	        if (reservation.getStatus() == ReservationStatus.CHECKED_IN ||
 81	            reservation.getStatus() == ReservationStatus.CHECKED_OUT ||
 82	            reservation.getStatus() == ReservationStatus.CANCELLED) {
 83	            throw new OperationNotAllowedException("Cannot cancel a reservation that has been checked in or is already cancelled");
 84	        }
 85	
 86	        reservation.setStatus(ReservationStatus.CANCELLED);
 87	
 88	        if (reservation.getRatePlan() == RatePlan.STANDARD && reservation.getAmountPaid().compareTo(BigDecimal.ZERO) > 0) {
 89	            reservation.setRefund(reservation.getAmountPaid());
 90	        } else {
 91	            reservation.setRefund(BigDecimal.ZERO);
 92	        }
 93	
 94	        return reservation;
 95	    }
 96	
 97	    public Reservation checkIn(long id) {
 98	        Reservation reservation = getReservation(id);
 99	
100	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
101	            throw new OperationNotAllowedException("Only confirmed reservations can be checked in");
102	        }
103	
104	        reservation.setStatus(ReservationStatus.CHECKED_IN);
105	        return reservation;
106	    }
107	
108	    public ReceiptDocument checkOut(long id) {
109	        Reservation reservation = getReservation(id);
110	
111	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
112	            throw new OperationNotAllowedException("Only checked-in reservations can be checked out");
113	        }
114	
115	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
116	        return createReceipt(reservation);
117	    }
118	
119	    public ReceiptDocument getDocument(long id) {
120	        Reservation reservation = getReservation(id);
121	
122	        if (!reservation.isPaid()) {
123	            throw new OperationNotAllowedException("Document is only available for paid reservations");
124	        }
125	
126	        return createReceipt(reservation);
127	    }
128	
129	    public Reservation getReservation(long id) {
130	        return reservationRepository.findById(id)
131	                .orElseThrow(() -> new ReservationNotFoundException("Reservation " + id + " not found"));
132	    }
133	
134	    private BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
135	        BigDecimal subtotal = BigDecimal.ZERO;
136	        LocalDate date = checkIn;
137	
138	        while (date.isBefore(checkOut)) {
139	            BigDecimal nightPrice = pricingService.calculateNightPrice(baseRate, date);
140	            subtotal = subtotal.add(nightPrice);
141	            date = date.plusDays(1);
142	        }
143	
144	        return pricingService.round(subtotal);
145	    }
146	
147	    private BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
148	        BigDecimal discount = subtotal.multiply(ratePlan.getDiscountRate());
149	        return pricingService.round(discount);
150	    }
151	
152	    private ReceiptDocument createReceipt(Reservation reservation) {
153	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
154	
155	        return new ReceiptDocument(
156	                "Comprovante de reserva",
157	                reservation.getId(),
158	                reservation.getGuestName(),
159	                reservation.getGuestCpf(),
160	                reservation.getRoomNumber(),
161	                room.getType(),
162	                reservation.getCheckIn(),
163	                reservation.getCheckOut(),
164	                reservation.getNights(),
165	                reservation.getSubtotal(),
166	                reservation.getDiscount(),
167	                reservation.getTotal()
168	        );
169	    }
170	
171	    private void sendConfirmationEmail(Reservation reservation) {
172	        ReceiptDocument receipt = createReceipt(reservation);
173	        String body = formatConfirmationEmail(receipt);
174	
175	        long messageId = messageRepository.nextId();
176	        Message message = new Message(
177	                messageId,
178	                "EMAIL",
179	                reservation.getGuestEmail(),
180	                "Reserva confirmada - Pousada Maré Alta",
181	                body
182	        );
183	
184	        messageRepository.save(message);
185	    }
186	
187	    private String formatConfirmationEmail(ReceiptDocument receipt) {
188	        String receiptText = formatReceipt(receipt);
189	
190	        return String.format("Olá, %s!\n\n" +
191	                "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
192	                "%s\n\n" +
193	                "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
194	                "Até breve!",
195	                receipt.getGuestName(),
196	                receiptText);
197	    }
198	
199	    private String formatReceipt(ReceiptDocument receipt) {
200	        StringBuilder sb = new StringBuilder();
201	        sb.append(String.format("Comprovante de reserva nº %d\n", receipt.getReservationId()));
202	        sb.append(String.format("Hóspede: %s (CPF %s)\n", receipt.getGuestName(), formatCpf(receipt.getGuestCpf())));
203	        sb.append(String.format("Quarto: %s (%s)\n", receipt.getRoomNumber(), receipt.getRoomType()));
204	        sb.append(String.format("Entrada: %s | Saída: %s | %d %s\n",
205	                formatDate(receipt.getCheckIn()),
206	                formatDate(receipt.getCheckOut()),
207	                receipt.getNights(),
208	                receipt.getNights() == 1 ? "diária" : "diárias"));
209	        sb.append(String.format("Diárias: %s\n", formatMoney(receipt.getSubtotal())));
210	
211	        if (receipt.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
212	            sb.append(String.format("Desconto: %s\n", formatMoney(receipt.getDiscount())));
213	        }
214	
215	        sb.append(String.format("Total: %s", formatMoney(receipt.getTotal())));
216	
217	        return sb.toString();
218	    }
219	
220	    private String formatCpf(String cpf) {
221	        if (cpf.length() == 11) {
222	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
223	        }
224	        return cpf;
225	    }
226	
227	    private String formatDate(LocalDate date) {
228	        return String.format("%02d/%02d/%04d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
229	    }
230	
231	    private String formatMoney(BigDecimal amount) {
232	        return String.format("R$ %,.2f", amount).replace(',', 'X').replace('.', ',').replace('X', '.');
233	    }
234	}

